#include "torchcli/ops.hpp"
#include "torchcli/safetensors.hpp"
#include <torch/torch.h>
#include <ATen/CPUGeneratorImpl.h>
#include <algorithm>
#include <cmath>
#include <cstring>
#include <limits>
#include <random>

namespace {
using namespace lmcpp;
using torchcli::TensorBundle;
using torchcli::TensorData;
using torchcli::TensorRef;
torch::ScalarType scalar_type(const std::string&d){if(d=="F32")return torch::kFloat32;if(d=="F64")return torch::kFloat64;if(d=="I64")return torch::kInt64;throw Error{ErrorCode::ValidationError,"dtype must be F32, F64, or I64",{{"tool_code","INVALID_DTYPE"}}};}
std::string dtype_name(torch::ScalarType t){if(t==torch::kFloat32)return "F32";if(t==torch::kFloat64)return "F64";if(t==torch::kInt64)return "I64";throw Error{ErrorCode::ValidationError,"unsupported tensor dtype",{{"tool_code","UNSUPPORTED_DTYPE"}}};}
torch::Tensor tensor_from(const TensorData&d){auto t=torch::empty(d.shape,torch::TensorOptions().dtype(scalar_type(d.dtype)).device(torch::kCPU));if(t.nbytes()!=d.bytes.size())throw Error{ErrorCode::CommandFailed,"tensor payload has invalid size",{{"tool_code","INVALID_ARTIFACT"}}};if(!d.bytes.empty())std::memcpy(t.data_ptr(),d.bytes.data(),d.bytes.size());return t;}
TensorData tensor_to(const torch::Tensor&input){auto t=input.contiguous().cpu();TensorData d;d.dtype=dtype_name(t.scalar_type());d.shape.assign(t.sizes().begin(),t.sizes().end());d.bytes.resize(t.nbytes());if(!d.bytes.empty())std::memcpy(d.bytes.data(),t.data_ptr(),d.bytes.size());return d;}
TensorRef ref(const Json&j,const char*k){return torchcli::parse_ref(j.at(k).get<std::string>());}
TensorRef out_ref(const Json&j){auto path=j.at("out").get<std::string>();if(path.find('#')!=std::string::npos)throw Error{ErrorCode::ValidationError,"output path cannot contain #",{{"tool_code","INVALID_OUTPUT_PATH"}}};return{path,"tensor"};}
Param param(std::string n,Type t,bool req=true,std::string occurs="1",Json def=nullptr){Param p;p.name=std::move(n);p.type=t;p.required=req;p.occurs=std::move(occurs);p.default_value=std::move(def);return p;}
Json desc(const TensorRef&r,const TensorData&d){return torchcli::descriptor(r,d);}
Json descriptors(const TensorBundle&b,const std::string&path){Json out=Json::object();for(const auto&item:b.tensors)out[item.first]=desc({path,item.first},item.second);return out;}
void same_type_shape(const TensorData&a,const TensorData&b,const char*op){if(a.dtype!=b.dtype)throw Error{ErrorCode::ValidationError,std::string(op)+" inputs must have matching dtypes",{{"tool_code","DTYPE_MISMATCH"}}};if(a.shape!=b.shape)throw Error{ErrorCode::ValidationError,std::string(op)+" inputs must have identical shapes",{{"tool_code","SHAPE_MISMATCH"}}};}
uint64_t positive_shape(const Json&j,std::vector<int64_t>&dims,const std::string&op="shape"){
  uint64_t n=1;for(const auto&v:j){double x=v.get<double>();if(!std::isfinite(x)||x<1||std::floor(x)!=x||x>static_cast<double>(std::numeric_limits<int64_t>::max()))throw Error{ErrorCode::ValidationError,op+" dimensions must be positive integers",{{"tool_code","INVALID_SHAPE"}}};auto d=static_cast<uint64_t>(x);if(n>256ull*1024*1024/8/d)throw Error{ErrorCode::ValidationError,"tensor exceeds artifact size limit",{{"tool_code","OUTPUT_TOO_LARGE"}}};n*=d;dims.push_back(static_cast<int64_t>(d));}if(dims.empty())throw Error{ErrorCode::ValidationError,op+" must not be empty",{{"tool_code","INVALID_SHAPE"}}};return n;
}
TensorData checkpoint_tensor(const TensorBundle&b,const char*name){auto it=b.tensors.find(name);if(it==b.tensors.end())throw Error{ErrorCode::ValidationError,std::string("checkpoint is missing ")+name,{{"tool_code","INVALID_CHECKPOINT"}}};return it->second;}
void check_checkpoint(const TensorBundle&b){auto f=b.metadata.find("torchcli_format"),a=b.metadata.find("arch");if(f==b.metadata.end()||f->second!="1"||a==b.metadata.end()||a->second!="mlp_relu_v1")throw Error{ErrorCode::ValidationError,"unsupported MLP checkpoint metadata",{{"tool_code","INVALID_CHECKPOINT"}}};}
torch::Tensor forward_mlp(const TensorBundle&b,const torch::Tensor&x){auto w1=tensor_from(checkpoint_tensor(b,"w1")),b1=tensor_from(checkpoint_tensor(b,"b1")),w2=tensor_from(checkpoint_tensor(b,"w2")),b2=tensor_from(checkpoint_tensor(b,"b2"));if(w1.dim()!=2||w1.size(1)!=2||b1.sizes()!=torch::IntArrayRef({w1.size(0)})||w2.dim()!=2||w2.size(0)!=1||w2.size(1)!=w1.size(0)||b2.numel()!=1)throw Error{ErrorCode::ValidationError,"checkpoint tensors have incompatible MLP shapes",{{"tool_code","INVALID_CHECKPOINT"}}};return x.matmul(w1.transpose(0,1)).add(b1).relu().matmul(w2.transpose(0,1)).add(b2);}
}
lmcpp::CliSpec make_torchcli_spec(){
  using namespace lmcpp;CliSpec spec{"torchcli","0.2.0",{}};
  auto write_op=[](std::string name,std::string description){Operation o;o.name=std::move(name);o.access=Access::Write;o.description=std::move(description);o.returns="object";return o;};
  auto shape_param=param("shape",Type::Number,true,"+");
  Operation create=write_op("tensor_create","Create a dense CPU tensor artifact");auto dtype=param("dtype",Type::String,false,"?","F32");dtype.enum_values={"F32","F64","I64"};create.params={shape_param,dtype,param("fill",Type::Number,false),param("values",Type::Json,false),param("out",Type::String)};
  create.handler=[](const Params&p){std::string dtype=p.value("dtype","F32");auto st=scalar_type(dtype);std::vector<int64_t>dims;uint64_t count=positive_shape(p.at("shape"),dims);if(count>256ull*1024*1024/(st==torch::kFloat32?4:8))throw Error{ErrorCode::ValidationError,"tensor exceeds artifact size limit",{{"tool_code","OUTPUT_TOO_LARGE"}}};if(p.contains("fill")&&p.contains("values"))throw Error{ErrorCode::ValidationError,"fill and values are mutually exclusive",{{"tool_code","INVALID_VALUE"}}};torch::Tensor t;
    if(p.contains("values")){const Json&v=p.at("values");if(!v.is_array()||v.size()!=count)throw Error{ErrorCode::ValidationError,"values count must match shape",{{"tool_code","INVALID_VALUE"}}};std::vector<double>vals;for(const auto&x:v){double n=x.get<double>();if(!std::isfinite(n))throw Error{ErrorCode::ValidationError,"values must be finite",{{"tool_code","INVALID_VALUE"}}};vals.push_back(n);}t=torch::tensor(vals,torch::TensorOptions().dtype(st).device(torch::kCPU)).reshape(dims);}else{double value=p.value("fill",0.0);if(!std::isfinite(value))throw Error{ErrorCode::ValidationError,"fill must be finite",{{"tool_code","INVALID_VALUE"}}};if(st==torch::kFloat32&&std::abs(value)>std::numeric_limits<float>::max())throw Error{ErrorCode::ValidationError,"F32 fill is out of range",{{"tool_code","INVALID_VALUE"}}};if(st==torch::kInt64&&(std::floor(value)!=value||value<static_cast<double>(std::numeric_limits<int64_t>::min())||value>=static_cast<double>(std::numeric_limits<int64_t>::max())))throw Error{ErrorCode::ValidationError,"I64 fill must be an in-range integer",{{"tool_code","INVALID_VALUE"}}};t=torch::full(dims,value,torch::TensorOptions().dtype(st).device(torch::kCPU));}
    auto data=tensor_to(t);auto r=out_ref(p);torchcli::write_tensor(r.path,data);return desc(r,data);};
  Operation rand=write_op("tensor_rand","Create a seeded uniform tensor artifact");rand.params={shape_param,param("dtype",Type::String,false,"?","F32"),param("distribution",Type::String,false,"?","uniform"),param("seed",Type::Number),param("out",Type::String)};rand.params[1].enum_values={"F32","F64","I64"};rand.params[2].enum_values={"uniform"};
  rand.handler=[](const Params&p){std::vector<int64_t>dims;uint64_t count=positive_shape(p.at("shape"),dims);auto st=scalar_type(p.value("dtype","F32"));std::string dt=dtype_name(st);if(count>256ull*1024*1024/(st==torch::kFloat32?4:8))throw Error{ErrorCode::ValidationError,"tensor exceeds artifact size limit",{{"tool_code","OUTPUT_TOO_LARGE"}}};double seed_value=p.at("seed").get<double>();if(!std::isfinite(seed_value)||seed_value<0||std::floor(seed_value)!=seed_value||seed_value>9007199254740991.0)throw Error{ErrorCode::ValidationError,"seed must be a nonnegative safe integer",{{"tool_code","INVALID_SEED"}}};uint64_t seed=static_cast<uint64_t>(seed_value);auto generator=at::detail::createCPUGenerator(seed);auto options=torch::TensorOptions().dtype(st).device(torch::kCPU);auto t=st==torch::kInt64?torch::randint(0,1000,dims,generator,options):torch::rand(dims,generator,options);auto data=tensor_to(t);auto r=out_ref(p);torchcli::write_tensor(r.path,data);auto result=desc(r,data);result["seed"]=seed;return result;};
  Operation matmul=write_op("tensor_matmul","Multiply two rank-2 dense CPU tensors");matmul.params={param("a",Type::String),param("b",Type::String),param("out",Type::String)};matmul.handler=[](const Params&p){auto ar=ref(p,"a"),br=ref(p,"b"),or_=out_ref(p);auto ad=torchcli::read_tensor(ar),bd=torchcli::read_tensor(br);if(ad.dtype!=bd.dtype)throw Error{ErrorCode::ValidationError,"matmul inputs must have matching dtypes",{{"tool_code","DTYPE_MISMATCH"}}};if(ad.shape.size()!=2||bd.shape.size()!=2||ad.shape[1]!=bd.shape[0])throw Error{ErrorCode::ValidationError,"matmul requires compatible rank-2 shapes",{{"tool_code","SHAPE_MISMATCH"}}};auto data=tensor_to(tensor_from(ad).matmul(tensor_from(bd)));torchcli::write_tensor(or_.path,data);return desc(or_,data);};
  Operation add=write_op("tensor_add","Add equal-shaped tensors without broadcasting");add.params={param("a",Type::String),param("b",Type::String),param("out",Type::String)};add.handler=[](const Params&p){auto ar=ref(p,"a"),br=ref(p,"b"),or_=out_ref(p);auto ad=torchcli::read_tensor(ar),bd=torchcli::read_tensor(br);same_type_shape(ad,bd,"add");auto data=tensor_to(tensor_from(ad)+tensor_from(bd));torchcli::write_tensor(or_.path,data);return desc(or_,data);};
  Operation soft=write_op("tensor_softmax","Apply softmax along a checked dimension");soft.params={param("input",Type::String),param("dim",Type::Number),param("out",Type::String)};soft.handler=[](const Params&p){auto ir=ref(p,"input"),or_=out_ref(p);auto d=torchcli::read_tensor(ir);if(d.dtype=="I64")throw Error{ErrorCode::ValidationError,"softmax requires floating point input",{{"tool_code","INVALID_DTYPE"}}};auto t=tensor_from(d);double dim_value=p.at("dim").get<double>();if(!std::isfinite(dim_value)||std::floor(dim_value)!=dim_value||dim_value<std::numeric_limits<int64_t>::min()||dim_value>std::numeric_limits<int64_t>::max())throw Error{ErrorCode::ValidationError,"softmax dimension must be an integer",{{"tool_code","INVALID_DIM"}}};int64_t dim=static_cast<int64_t>(dim_value);if(dim<0)dim+=t.dim();if(dim<0||dim>=t.dim())throw Error{ErrorCode::ValidationError,"softmax dimension out of range",{{"tool_code","INVALID_DIM"}}};auto data=tensor_to(torch::softmax(t,dim));torchcli::write_tensor(or_.path,data);return desc(or_,data);};
  Operation linear=write_op("tensor_linear","Apply X W-transpose plus optional bias");linear.params={param("input",Type::String),param("weight",Type::String),param("bias",Type::String,false,"?"),param("out",Type::String)};linear.handler=[](const Params&p){auto ir=ref(p,"input"),wr=ref(p,"weight"),or_=out_ref(p);auto xd=torchcli::read_tensor(ir),wd=torchcli::read_tensor(wr);if(xd.dtype!=wd.dtype)throw Error{ErrorCode::ValidationError,"linear inputs must have matching dtypes",{{"tool_code","DTYPE_MISMATCH"}}};if(xd.dtype=="I64")throw Error{ErrorCode::ValidationError,"linear requires floating point tensors",{{"tool_code","INVALID_DTYPE"}}};auto x=tensor_from(xd),w=tensor_from(wd);if(w.dim()!=2||x.dim()<1||x.size(-1)!=w.size(1))throw Error{ErrorCode::ValidationError,"linear input and weight shapes are incompatible",{{"tool_code","SHAPE_MISMATCH"}}};auto y=x.matmul(w.transpose(0,1));if(p.contains("bias")){auto bd=torchcli::read_tensor(torchcli::parse_ref(p.at("bias").get<std::string>()));if(bd.dtype!=xd.dtype||bd.shape!=std::vector<int64_t>{w.size(0)})throw Error{ErrorCode::ValidationError,"linear bias shape or dtype mismatch",{{"tool_code","SHAPE_MISMATCH"}}};y=y+tensor_from(bd);}auto data=tensor_to(y);torchcli::write_tensor(or_.path,data);return desc(or_,data);};
  Operation save=write_op("tensor_save","Pack named tensor references into one safetensors artifact");save.params={param("tensors",Type::Object),param("out",Type::String),param("metadata",Type::Object,false)};save.handler=[](const Params&p){TensorBundle b;for(auto it=p.at("tensors").begin();it!=p.at("tensors").end();++it){if(!it.value().is_string())throw Error{ErrorCode::ValidationError,"tensor refs must be strings",{{"tool_code","INVALID_TENSOR_REF"}}};if(it.key().empty()||it.key()=="__metadata__")throw Error{ErrorCode::ValidationError,"invalid tensor name",{{"tool_code","INVALID_TENSOR_NAME"}}};auto r=torchcli::parse_ref(it.value().get<std::string>());b.tensors.emplace(it.key(),torchcli::read_tensor(r));}if(p.contains("metadata")){for(auto it=p.at("metadata").begin();it!=p.at("metadata").end();++it){if(!it.value().is_string())throw Error{ErrorCode::ValidationError,"metadata values must be strings",{{"tool_code","INVALID_METADATA"}}};b.metadata[it.key()]=it.value().get<std::string>();}}auto path=out_ref(p).path;torchcli::write_bundle(path,b);return Json{{"path",path},{"tensors",descriptors(b,path)}};};
  Operation load=write_op("tensor_load","Validate and reserialize safetensors into a new artifact");load.params={param("path",Type::String),param("key",Type::String,false,"?"),param("out",Type::String)};load.handler=[](const Params&p){auto b=torchcli::read_bundle(p.at("path").get<std::string>());if(p.contains("key")){auto it=b.tensors.find(p.at("key").get<std::string>());if(it==b.tensors.end())throw Error{ErrorCode::NotFound,"tensor key not found",{{"tool_code","TENSOR_NOT_FOUND"}}};TensorData selected=it->second;b.tensors.clear();b.tensors.emplace(p.at("key").get<std::string>(),std::move(selected));}auto path=out_ref(p).path;torchcli::write_bundle(path,b);return Json{{"path",path},{"tensors",descriptors(b,path)}};};
  Operation inspect;inspect.name="tensor_inspect";inspect.access=Access::Read;inspect.description="Inspect tensor metadata and a bounded value preview";inspect.returns="object";inspect.params={param("input",Type::String),param("limit",Type::Number,false,"?",32)};inspect.handler=[](const Params&p){auto r=ref(p,"input");auto d=torchcli::read_tensor(r);auto t=tensor_from(d);double lim=p.value("limit",32.0);if(!std::isfinite(lim)||lim<0||std::floor(lim)!=lim||lim>32)throw Error{ErrorCode::ValidationError,"limit must be an integer from 0 through 32",{{"tool_code","INVALID_LIMIT"}}};Json values=Json::array();uint64_t nonfinite=0;uint64_t n=static_cast<uint64_t>(t.numel()),take=std::min<uint64_t>(n,static_cast<uint64_t>(lim));for(uint64_t i=0;i<take;++i){if(t.scalar_type()==torch::kInt64)values.push_back(t.data_ptr<int64_t>()[i]);else{double x=t.scalar_type()==torch::kFloat32?static_cast<double>(t.data_ptr<float>()[i]):t.data_ptr<double>()[i];if(std::isfinite(x))values.push_back(x);else{values.push_back(nullptr);++nonfinite;}}}auto result=desc(r,d);result["values"]=values;result["nonfinite_count"]=nonfinite;return result;};
  Operation grad=write_op("autograd_grad","Rebuild sum-of-squares graph and persist its gradient");grad.params={param("input",Type::String),param("function",Type::String,false,"?","sum_square"),param("out",Type::String)};grad.params[1].enum_values={"sum_square"};grad.handler=[](const Params&p){auto ir=ref(p,"input"),or_=out_ref(p);auto d=torchcli::read_tensor(ir);if(d.dtype=="I64")throw Error{ErrorCode::ValidationError,"autograd requires floating point input",{{"tool_code","INVALID_DTYPE"}}};auto x=tensor_from(d).detach().set_requires_grad(true);auto loss=x.pow(2).sum();loss.backward();auto dx=tensor_to(x.grad());torchcli::write_tensor(or_.path,dx);return Json{{"dx",desc(or_,dx)},{"loss",loss.item<double>()}};};
  Operation forward=write_op("mlp_forward","Run fixed two-layer ReLU MLP inference");forward.params={param("checkpoint",Type::String),param("input",Type::String),param("out",Type::String)};forward.handler=[](const Params&p){auto bundle=torchcli::read_bundle(p.at("checkpoint").get<std::string>());check_checkpoint(bundle);auto xdata=torchcli::read_tensor(ref(p,"input"));if(xdata.dtype=="I64")throw Error{ErrorCode::ValidationError,"MLP input must be floating point",{{"tool_code","INVALID_DTYPE"}}};torch::NoGradGuard guard;auto data=tensor_to(forward_mlp(bundle,tensor_from(xdata)));auto r=out_ref(p);torchcli::write_tensor(r.path,data);return desc(r,data);};
  Operation train=write_op("mlp_train_step","Train one MLP step with MSE and plain SGD");train.params={param("checkpoint",Type::String),param("input",Type::String),param("target",Type::String),param("lr",Type::Number),param("out",Type::String)};train.handler=[](const Params&p){auto bundle=torchcli::read_bundle(p.at("checkpoint").get<std::string>());check_checkpoint(bundle);auto xd=torchcli::read_tensor(ref(p,"input")),yd=torchcli::read_tensor(ref(p,"target"));if(xd.dtype!=yd.dtype||xd.dtype=="I64")throw Error{ErrorCode::ValidationError,"training inputs and targets must share a floating dtype",{{"tool_code","DTYPE_MISMATCH"}}};auto x=tensor_from(xd),y=tensor_from(yd);if(y.numel()==0)throw Error{ErrorCode::ValidationError,"training target must not be empty",{{"tool_code","SHAPE_MISMATCH"}}};double lr=p.at("lr").get<double>();if(!std::isfinite(lr)||lr<=0||lr>10)throw Error{ErrorCode::ValidationError,"learning rate must be finite and in (0,10]",{{"tool_code","INVALID_LR"}}};auto w1=tensor_from(checkpoint_tensor(bundle,"w1")).detach().set_requires_grad(true),b1=tensor_from(checkpoint_tensor(bundle,"b1")).detach().set_requires_grad(true),w2=tensor_from(checkpoint_tensor(bundle,"w2")).detach().set_requires_grad(true),b2=tensor_from(checkpoint_tensor(bundle,"b2")).detach().set_requires_grad(true);auto prediction=x.matmul(w1.transpose(0,1)).add(b1).relu().matmul(w2.transpose(0,1)).add(b2);if(prediction.sizes()!=y.sizes())throw Error{ErrorCode::ValidationError,"prediction and target shapes must match",{{"tool_code","SHAPE_MISMATCH"}}};auto loss=torch::mse_loss(prediction,y);loss.backward();{torch::NoGradGuard guard;w1.sub_(w1.grad()*lr);b1.sub_(b1.grad()*lr);w2.sub_(w2.grad()*lr);b2.sub_(b2.grad()*lr);}bundle.tensors["w1"]=tensor_to(w1);bundle.tensors["b1"]=tensor_to(b1);bundle.tensors["w2"]=tensor_to(w2);bundle.tensors["b2"]=tensor_to(b2);uint64_t step=0;auto si=bundle.metadata.find("step");if(si!=bundle.metadata.end())try{step=std::stoull(si->second);}catch(...){throw Error{ErrorCode::ValidationError,"invalid checkpoint step metadata",{{"tool_code","INVALID_CHECKPOINT"}}};}bundle.metadata["torchcli_format"]="1";bundle.metadata["arch"]="mlp_relu_v1";bundle.metadata["step"]=std::to_string(step+1);auto path=out_ref(p).path;torchcli::write_bundle(path,bundle);return Json{{"path",path},{"tensors",descriptors(bundle,path)},{"loss",loss.item<double>()},{"step",step+1}};};
  spec.operations={create,rand,matmul,add,soft,linear,save,load,inspect,grad,forward,train};return spec;
}
